package io.github.dirtyredz.herbalwitch.fixture;

import net.minecraft.commands.CommandSourceStack;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;

/**
 * Showcase GameTests run the real registered command from a fake player standing on a stone floor
 * at relative (0, 1, 1); the box then starts at relative (2, 0, 1). Templates are generated by
 * tools/generate-test-structures.mjs.
 */
public final class ShowcaseFixtures {
    /** Fits the full showcase plus the entrance aisle. */
    public static final String FULL = "showcase";
    public static final int FULL_X = 128;
    public static final int FULL_Z = 40;
    /** Fits one small section. */
    public static final String SECTION = "showcase_section";
    public static final int SECTION_X = 16;
    public static final int SECTION_Z = 12;
    /** Where the player stands; the box's minimum corner is two blocks east, on the floor. */
    public static final BlockPos STAND = new BlockPos(0, 1, 1);
    public static final BlockPos ORIGIN = new BlockPos(2, 0, 1);

    private ShowcaseFixtures() {
    }

    public static void stoneFloor(GameTestHelper helper, int width, int depth) {
        for (int x = 0; x < width; x++) {
            for (int z = 0; z < depth; z++) {
                helper.setBlock(new BlockPos(x, 0, z), Blocks.STONE);
            }
        }
    }

    /** A fake player standing at {@link #STAND}. */
    public static ServerPlayer standing(GameTestHelper helper, String name, GameType mode) {
        ServerPlayer player = PlayerFixtures.player(helper, name, mode, Direction.EAST);
        BlockPos feet = helper.absolutePos(STAND);
        player.moveTo(feet.getX() + 0.5, feet.getY(), feet.getZ() + 0.5, Direction.EAST.toYRot(), 0);
        return player;
    }

    /** Runs a command line through the server's real dispatcher; returns its result (0 on failure). */
    public static int run(GameTestHelper helper, CommandSourceStack source, String command) {
        return helper.getLevel().getServer().getCommands().performPrefixedCommand(source.withSuppressedOutput(), command);
    }

    public static CommandSourceStack as(ServerPlayer player, int permission) {
        return player.createCommandSourceStack().withPermission(permission);
    }
}
